     8	import React from 'react';
     9	import loadable from '@loadable/component';
    10	import { getConfig } from '@salesforce/pwa-kit-runtime/utils/ssr-config';
    11	
    12	// Components
    13	import { Skeleton } from '@salesforce/retail-react-app/app/components/shared/ui';
    14	import { configureRoutes } from '@salesforce/retail-react-app/app/utils/routes-utils';
    15	import { routes as _routes } from '@salesforce/retail-react-app/app/routes';
    16	
    17	const fallback = <Skeleton height="75vh" width="100%" />;
    18	
    19	// Create your pages here and add them to the routes array
    20	// Use loadable to split code into smaller js chunks
    21	const Home = loadable(() => import('./pages/home'), { fallback });
    22	const MyNewRoute = loadable(() => import('./pages/my-new-route'));
    23	const Experience = loadable(() => import('./pages/experience'), { fallback });
    24	const ContentfulPreview = loadable(() => import('./pages/contentfulPreview'), { fallback });
    25	const ProductDetail = loadable(() => import('./pages/product-detail'), { fallback });
    26	
    27	const routes = [
    28	  {
    29	    path: '/',
    30	    component: Home,
    31	    exact: true,
    32	  },
    33	  {
    34	    path: '/my-new-route',
    35	    component: MyNewRoute,
    36	  },
    37	  {
    38	    path: '/product/:productId',
    39	    component: ProductDetail,
    40	  },
    41	  ..._routes,
    42	  // Contentful Live Preview — must be before /:slug so it takes priority.
    43	  {
    44	    path: '/preview',
    45	    component: ContentfulPreview,
    46	    exact: true,
    47	  },
    48	  // Contentful Studio/Experience pages — fallback after all SFCC routes.
    49	  // `configureRoutes` strips PWA Kit's '*' catch-all so this is safely reached only for paths no other route matched.
    50	  {
    51	    path: '/:slug',
    52	    component: Experience,
    53	  },
    54	];
    55	
    56	const configureAppRoutes = () => {
    57	  const config = getConfig();
    58	  return configureRoutes(routes, config, {
    59	    ignoredRoutes: ['/callback', '*'],
    60	  });
    61	};
    62	
    63	export default configureAppRoutes;

