 1	import React from 'react';
 2	import DOMPurify from 'isomorphic-dompurify';
 3	import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
 4	import { SPACE_DESCRIPTION_TO_META, SPACE_MODEL_INFO_TO_STYLE_CODE } from 'app/theme/components/pdpProductInfo';
 5	
 6	type PdpProductInfoProps = {
 7	  name: string;
 8	  price: string;
 9	  description?: string;
10	  modelInfo?: string;
11	  styleCode?: string;
12	};
13	
14	// ---------------------------------------------------------------------------
15	// All styling lives in theme/components/pdpProductInfo.ts and is consumed via
16	// useMultiStyleConfig('ZimmPdpProductInfo') → __css. The only exceptions are the
17	// two conditional bottom margins, which depend on which optional props were
18	// supplied and so cannot be expressed in baseStyle; their values are imported
19	// from the theme file rather than written here.
20	// ---------------------------------------------------------------------------
21	
22	/**
23	 * Renders static product information for the PDP: name, price, description,
24	 * and optional model copy / style code.
25	 */
26	const PdpProductInfo = ({ name, price, description, modelInfo, styleCode }: PdpProductInfoProps) => {
27	  const styles = useMultiStyleConfig('ZimmPdpProductInfo', {});
28	  const hasMeta = Boolean(modelInfo || styleCode);
29	
30	  return (
31	    <chakra.div>
32	      <chakra.h1 __css={styles.name}>{name}</chakra.h1>
33	
34	      <chakra.p data-testid="product-price" __css={styles.price}>
35	        {price}
36	      </chakra.p>
37	
38	      {description && (
39	        <chakra.div
40	          data-testid="product-description"
41	          __css={styles.description}
42	          marginBottom={hasMeta ? SPACE_DESCRIPTION_TO_META : 0}
43	          dangerouslySetInnerHTML={{ __html: DOMPurify.sanitize(description) }}
44	        />
45	      )}
46	
47	      {hasMeta && (
48	        <chakra.div>
49	          {modelInfo && (
50	            <chakra.div
51	              data-testid="product-model-info"
52	              __css={styles.modelInfo}
53	              marginBottom={styleCode ? SPACE_MODEL_INFO_TO_STYLE_CODE : 0}
54	              dangerouslySetInnerHTML={{ __html: DOMPurify.sanitize(modelInfo) }}
55	            />
56	          )}
57	          {styleCode && (
58	            <chakra.p data-testid="product-style-code" __css={styles.styleCode}>
59	              Style Code: {styleCode}
60	            </chakra.p>
61	          )}
62	        </chakra.div>
63	      )}
64	    </chakra.div>
65	  );
66	};
67	
68	export { PdpProductInfo };
69	export default PdpProductInfo;

